SELECT 'inspection_charges' as tabela, COUNT(*) as total FROM inspection_charges 
WHERE LOWER(client_email) LIKE '%test%' OR LOWER(vessel_name) LIKE '%test%';

SELECT 'fuel_records' as tabela, COUNT(*) as total FROM fuel_records 
WHERE LOWER(vessel_name) LIKE '%test%' OR LOWER(client_email) LIKE '%test%';

SELECT 'asaas_customers' as tabela, COUNT(*) as total FROM asaas_customers 
WHERE LOWER(client_email) LIKE '%test%' OR LOWER(name) LIKE '%test%';

SELECT 'maintenances' as tabela, COUNT(*) as total FROM maintenances 
WHERE LOWER(description) LIKE '%test%' OR LOWER(vessel_name) LIKE '%test%';

SELECT 'inspections' as tabela, COUNT(*) as total FROM inspections 
WHERE LOWER(vessel_name) LIKE '%test%';

SELECT 'payment_audit_logs' as tabela, COUNT(*) as total FROM payment_audit_logs 
WHERE LOWER(client_email) LIKE '%test%';

